// taskboard: worked SaaS example, generated by `prodforge init saas-web taskboard`
// and extended with a real feature: an in-memory task board API.
// Runtime deps: node builtins only. Run: npm install && npm test && npm start.
import { createServer, type IncomingMessage, type ServerResponse } from "node:http";

export interface Task {
  id: number;
  title: string;
  done: boolean;
}

export function healthPayload(): { ok: boolean; service: string } {
  return { ok: true, service: "taskboard" };
}

export class TaskStore {
  private tasks: Task[] = [];
  private nextId = 1;

  list(): Task[] {
    return [...this.tasks];
  }

  create(title: unknown): Task {
    if (typeof title !== "string" || title.trim().length === 0) {
      throw new Error("title must be a non-empty string");
    }
    const task: Task = { id: this.nextId, title: title.trim(), done: false };
    this.nextId += 1;
    this.tasks.push(task);
    return task;
  }
}

const defaultStore = new TaskStore();

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
}

function readJsonBody(req: IncomingMessage): Promise<unknown> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => chunks.push(chunk));
    req.on("end", () => {
      try {
        resolve(JSON.parse(Buffer.concat(chunks).toString("utf8")));
      } catch {
        reject(new Error("body must be valid JSON"));
      }
    });
    req.on("error", reject);
  });
}

export function handleRequestWithStore(store: TaskStore): (req: IncomingMessage, res: ServerResponse) => void {
  return (req, res) => {
    if (req.url === "/health" && req.method === "GET") {
      sendJson(res, 200, healthPayload());
      return;
    }
    if (req.url === "/tasks" && req.method === "GET") {
      sendJson(res, 200, store.list());
      return;
    }
    if (req.url === "/tasks" && req.method === "POST") {
      readJsonBody(req).then(
        (body) => {
          try {
            const title = (body as { title?: unknown } | null)?.title;
            sendJson(res, 201, store.create(title));
          } catch (err) {
            sendJson(res, 400, { error: err instanceof Error ? err.message : "invalid input" });
          }
        },
        (err) => sendJson(res, 400, { error: err instanceof Error ? err.message : "invalid input" }),
      );
      return;
    }
    sendJson(res, 404, { error: "not_found" });
  };
}

export function handleRequest(req: IncomingMessage, res: ServerResponse): void {
  handleRequestWithStore(defaultStore)(req, res);
}

export function createServerInstance(store: TaskStore = defaultStore) {
  return createServer(handleRequestWithStore(store));
}

if (process.argv[1] !== undefined && import.meta.url.endsWith(process.argv[1].split("/").pop() ?? "")) {
  const port = Number(process.env.PORT ?? 3000);
  createServerInstance().listen(port, () => console.log(`taskboard listening on ${port}`));
}
